import{_ as a,o as i,c as e,a0 as n}from"./chunks/framework.DhQjJcnt.js";const c=JSON.parse('{"title":"Advanced Usage","description":"","frontmatter":{},"headers":[],"relativePath":"en/advanced.md","filePath":"en/advanced.md","lastUpdated":1787985369000}'),t={name:"en/advanced.md"};function h(l,s,p,r,o,d){return i(),e("div",null,[...s[0]||(s[0]=[n(`<h1 id="advanced-usage" tabindex="-1">Advanced Usage <a class="header-anchor" href="#advanced-usage" aria-label="Permalink to &quot;Advanced Usage&quot;">​</a></h1><h2 id="end-to-end-encryption" tabindex="-1">End-to-end encryption <a class="header-anchor" href="#end-to-end-encryption" aria-label="Permalink to &quot;End-to-end encryption&quot;">​</a></h2><p>A matching passphrase on both sides enables ChaCha20-Poly1305 encryption (see <a href="./architecture#encryption-optional">Architecture</a>):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Host</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --service</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;our-passphrase&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Guest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-a3f9c2</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:25565</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --key</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;our-passphrase&quot;</span></span></code></pre></div><ul><li>A mismatch makes the session exit with <code>decryption failed (wrong --key?)</code></li><li>Encryption applies to <strong>P2P direct</strong> data frames (relay traffic is plaintext; see security notes)</li><li>The passphrase is passed on the command line — be aware of shell history; wrap it yourself in sensitive environments</li></ul><h2 id="multi-connection-reuse" tabindex="-1">Multi-connection reuse <a class="header-anchor" href="#multi-connection-reuse" aria-label="Permalink to &quot;Multi-connection reuse&quot;">​</a></h2><p>By default one session accepts <strong>unlimited sequential connections</strong> (reconnect, multiple logins — all reuse the same tunnel):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Cap at 3 connections; the session ends when exhausted</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-conns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-xxxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-conns</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span></span></code></pre></div><p>Great for: game client reconnects, or sharing with a strict connection cap.</p><blockquote><p>Note: connections are <strong>sequential</strong> (one at a time; reconnect right after a disconnect). Concurrent multiplexing is on the <a href="./roadmap">roadmap</a>.</p></blockquote><h2 id="force-relay" tabindex="-1">Force relay <a class="header-anchor" href="#force-relay" aria-label="Permalink to &quot;Force relay&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-xxxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --relay</span></span></code></pre></div><ul><li>Skips punching and goes straight through the server relay</li><li>For: known non-punchable NATs, server-side traffic logging, or quick link verification</li></ul><h2 id="tuning-the-punch-spread" tabindex="-1">Tuning the punch spread <a class="header-anchor" href="#tuning-the-punch-spread" aria-label="Permalink to &quot;Tuning the punch spread&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Widen the spread (try ±3~5 for symmetric NAT)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> join</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game-xxxx</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --spread</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 5</span></span></code></pre></div><ul><li>Default <code>--spread 2</code></li><li>Bigger spread = higher hit rate but more wasted packets (ICMP noise is ignored)</li><li>The two ends do not need to match</li></ul><h2 id="separate-udp-probe-port" tabindex="-1">Separate UDP probe port <a class="header-anchor" href="#separate-udp-probe-port" aria-label="Permalink to &quot;Separate UDP probe port&quot;">​</a></h2><p>When a cloud firewall requires separate TCP/UDP ports (see <a href="./config">Configuration</a>):</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_addr = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://101.43.41.195:8080&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">relay_addr     = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8081&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">signaling_udp  = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;101.43.41.195:8082&quot;</span></span></code></pre></div><h2 id="proxy-environments-http-signaling-via-proxy" tabindex="-1">Proxy environments (HTTP signaling via proxy) <a class="header-anchor" href="#proxy-environments-http-signaling-via-proxy" aria-label="Permalink to &quot;Proxy environments (HTTP signaling via proxy)&quot;">​</a></h2><p>The HTTP signaling client honors standard proxy environment variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Linux</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTP_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> HTTPS_PROXY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://127.0.0.1:7890</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Windows PowerShell</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:HTTP_PROXY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:7890&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$env:HTTPS_PROXY = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://127.0.0.1:7890&quot;</span></span></code></pre></div><blockquote><p>Only HTTP signaling goes through the proxy; UDP probing/punching and the relay TCP connection stay direct. If UDP is blocked by the network, use <code>--relay</code> mode instead.</p></blockquote><h2 id="debugging" tabindex="-1">Debugging <a class="header-anchor" href="#debugging" aria-label="Permalink to &quot;Debugging&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">frp-sh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --verbose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> create</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># frame-level logs: recv/send frame type, seq, ack, retransmits, etc.</span></span></code></pre></div><p>Frame log example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DEBUG frp_sh::p2p::stream] send to 127.0.0.1:49278: len=19</span></span>
<span class="line"><span>DEBUG frp_sh::p2p::stream] recv kind=Data seq=1 ack=1 len=4</span></span>
<span class="line"><span>DEBUG frp_sh::p2p::stream] recv kind=Ack seq=4 ack=3 len=0</span></span></code></pre></div><h2 id="common-host-service-recipes" tabindex="-1">Common host-service recipes <a class="header-anchor" href="#common-host-service-recipes" aria-label="Permalink to &quot;Common host-service recipes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scenario</th><th>Host command</th><th>Guest command</th></tr></thead><tbody><tr><td>Minecraft</td><td><code>create --service 127.0.0.1:25565</code></td><td><code>join &lt;room&gt; --listen 127.0.0.1:25565</code></td></tr><tr><td>SSH</td><td><code>create --service 127.0.0.1:22</code></td><td><code>join &lt;room&gt; --listen 127.0.0.1:2222</code></td></tr><tr><td>RDP</td><td><code>create --service 127.0.0.1:3389</code></td><td><code>join &lt;room&gt; --listen 127.0.0.1:3389</code></td></tr><tr><td>Any web service</td><td><code>create --service 127.0.0.1:8080</code></td><td><code>join &lt;room&gt; --listen 127.0.0.1:8080</code></td></tr></tbody></table>`,29)])])}const g=a(t,[["render",h]]);export{c as __pageData,g as default};
